$html = @'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Patient 360 â€” Clinical Intelligence Dashboard</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
<style>
:root {
  --topbar-bg: #0f172a;
  --nav-bg: #0b1120;
  --body-bg: #f8fafc;
  --card-bg: #ffffff;
  --border-color: #e2e8f0;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --primary-blue: #2563eb;
  --primary-blue-hover: #1d4ed8;
  --primary-orange: #f97316;
  --primary-orange-hover: #ea580c;
  --danger-red: #ef4444;
  --danger-red-bg: #fef2f2;
  --success-green: #10b981;
  --success-green-bg: #ecfdf5;
  --purple-badge: #8b5cf6;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -1px rgba(0,0,0,0.04);
  --radius-lg: 14px;
  --radius-md: 10px;
  --radius-sm: 6px;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background-color: var(--body-bg);
  color: var(--text-main);
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  font-size: 13px;
}

/* ================= TOP NAVIGATION BAR ================= */
.topbar {
  background: var(--topbar-bg);
  height: 52px;
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  color: #ffffff;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  z-index: 100;
}
.topbar-left {
  display: flex;
  align-items: center;
  gap: 20px;
}
.topbar-logo {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.5px;
  color: #ffffff;
  display: flex;
  align-items: center;
  gap: 6px;
}
.topbar-dropdown {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  color: #e2e8f0;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
}
.topbar-dropdown:hover { background: rgba(255,255,255,0.08); }

.topbar-search {
  flex: 0 1 480px;
  position: relative;
}
.topbar-search input {
  width: 100%;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 8px;
  padding: 8px 36px 8px 34px;
  color: #ffffff;
  font-size: 13px;
  outline: none;
  transition: all 0.2s;
}
.topbar-search input::placeholder { color: #94a3b8; }
.topbar-search input:focus {
  background: rgba(255,255,255,0.14);
  border-color: var(--primary-blue);
}
.search-icon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: #94a3b8;
  font-size: 14px;
}
.search-kbd {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(255,255,255,0.1);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 10px;
  color: #cbd5e1;
  font-family: monospace;
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: 16px;
}
.topbar-icon-btn {
  position: relative;
  background: transparent;
  border: none;
  color: #cbd5e1;
  cursor: pointer;
  font-size: 16px;
  padding: 6px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.topbar-icon-btn:hover { background: rgba(255,255,255,0.08); color: #ffffff; }
.badge-count {
  position: absolute;
  top: 2px;
  right: 2px;
  background: #ea580c;
  color: #ffffff;
  font-size: 10px;
  font-weight: 700;
  width: 15px;
  height: 15px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.topbar-user {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
}
.topbar-user:hover { background: rgba(255,255,255,0.08); }
.topbar-user img {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
  border: 1px solid rgba(255,255,255,0.3);
}
.user-info {
  display: flex;
  flex-direction: column;
  text-align: left;
}
.user-name { font-size: 13px; font-weight: 600; color: #ffffff; }
.user-role { font-size: 11px; color: #94a3b8; display: flex; align-items: center; gap: 4px; }

/* ================= APP LAYOUT ================= */
.app-container {
  display: flex;
  flex: 1;
  overflow: hidden;
}

/* 1. SLIM LEFT ICON RAIL */
.icon-rail {
  width: 54px;
  background: var(--nav-bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 0;
  gap: 8px;
  border-right: 1px solid rgba(255,255,255,0.06);
  z-index: 90;
}
.rail-btn {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #94a3b8;
  background: transparent;
  border: none;
  cursor: pointer;
  font-size: 17px;
  transition: all 0.15s ease;
}
.rail-btn:hover { background: rgba(255,255,255,0.08); color: #ffffff; }
.rail-btn.active {
  background: #2563eb;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(37,99,235,0.4);
}
.rail-divider { flex: 1; }

/* 2. SECONDARY SIDEBAR: PATIENT QUEUE */
.patient-queue {
  width: 260px;
  background: #ffffff;
  border-right: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.queue-header {
  padding: 14px 14px 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.queue-title { font-size: 15px; font-weight: 700; color: #0f172a; }
.queue-menu-btn {
  background: transparent;
  border: none;
  color: #94a3b8;
  cursor: pointer;
  font-size: 16px;
}
.queue-search {
  padding: 0 14px 10px;
}
.queue-search input {
  width: 100%;
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 7px 10px 7px 28px;
  font-size: 12px;
  outline: none;
}
.queue-search { position: relative; }
.queue-search .q-icon {
  position: absolute;
  left: 22px;
  top: 8px;
  color: #94a3b8;
  font-size: 12px;
}

.queue-tabs {
  display: flex;
  gap: 4px;
  padding: 0 12px 10px;
  overflow-x: auto;
}
.queue-tab {
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  border: 1px solid #e2e8f0;
  background: #ffffff;
  color: #64748b;
  cursor: pointer;
  white-space: nowrap;
}
.queue-tab.active {
  background: #0f172a;
  color: #ffffff;
  border-color: #0f172a;
}

.queue-list {
  flex: 1;
  overflow-y: auto;
  padding: 0 10px 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.patient-card {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 10px;
  cursor: pointer;
  transition: all 0.15s ease;
  position: relative;
}
.patient-card:hover {
  border-color: #cbd5e1;
  background: #f8fafc;
}
.patient-card.active {
  border: 1.5px solid #ef4444;
  background: #fffafa;
  box-shadow: 0 2px 8px rgba(239,68,68,0.12);
}
.patient-card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 6px;
}
.patient-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}
.patient-details {
  flex: 1;
  min-width: 0;
}
.patient-name {
  font-size: 13px;
  font-weight: 700;
  color: #0f172a;
}
.patient-sub {
  font-size: 10.5px;
  color: #64748b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.patient-tags {
  font-size: 10.5px;
  color: #475569;
  font-weight: 500;
  margin-bottom: 6px;
}
.patient-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 10.5px;
  color: #ea580c;
  font-weight: 600;
}
.badge-critical {
  background: #ef4444;
  color: #ffffff;
  font-size: 9px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 4px;
  letter-spacing: 0.5px;
}

/* 3. MAIN DASHBOARD CONTENT AREA */
.dashboard-main {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: #f8fafc;
}

/* ROW 1: TOP KPI METRICS */
.kpi-row {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
}
.kpi-card {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  box-shadow: var(--shadow-sm);
}
.kpi-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.kpi-label { font-size: 11px; font-weight: 600; color: var(--text-muted); }
.kpi-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
}
.kpi-val { font-size: 20px; font-weight: 800; color: #0f172a; line-height: 1.1; }
.kpi-sub { font-size: 10.5px; color: var(--text-muted); display: flex; align-items: center; gap: 4px; }
.kpi-sub.green { color: #16a34a; font-weight: 600; }
.kpi-sub.red { color: #dc2626; font-weight: 600; }

/* ROW 2: 3D ANATOMICAL BODY + AI SUMMARY */
.body-summary-row {
  display: grid;
  grid-template-columns: 2.2fr 1fr;
  gap: 12px;
}

/* 3D Anatomical Body Card */
.body-card {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 14px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  position: relative;
}
.body-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}
.body-pills {
  display: flex;
  gap: 6px;
}
.body-pill {
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  border: 1px solid var(--border-color);
  background: #ffffff;
  color: var(--text-muted);
  cursor: pointer;
}
.body-pill.active {
  background: #0f172a;
  color: #ffffff;
  border-color: #0f172a;
}
.fullscreen-btn {
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 600;
  color: #475569;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 4px;
}

.body-viewer-container {
  flex: 1;
  position: relative;
  min-height: 240px;
  background: #ffffff;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.body-img {
  max-width: 100%;
  max-height: 250px;
  object-fit: contain;
  display: block;
}
.body-controls {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  padding: 4px;
  box-shadow: var(--shadow-sm);
}
.body-ctrl-btn {
  width: 24px;
  height: 24px;
  background: transparent;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #475569;
  font-size: 14px;
  font-weight: 700;
  border-radius: 4px;
}
.body-ctrl-btn:hover { background: #f1f5f9; }

/* Interactive Callout on Heart */
.heart-callout {
  position: absolute;
  top: 28px;
  left: 36%;
  background: #ffffff;
  border: 1px solid #fed7aa;
  border-radius: 8px;
  padding: 8px 12px;
  box-shadow: 0 4px 12px rgba(249,115,22,0.15);
  font-size: 11px;
  min-width: 130px;
  z-index: 10;
  pointer-events: none;
}
.callout-header {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  color: #0f172a;
}
.callout-sub { font-size: 10px; color: #64748b; margin-top: 1px; }
.callout-score {
  font-size: 14px;
  font-weight: 800;
  color: #ef4444;
  margin-top: 2px;
}
.callout-trend { font-size: 9px; color: #ea580c; font-weight: 600; }

/* Hotspot pulse */
.hotspot-pulse {
  position: absolute;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: rgba(239,68,68,0.8);
  box-shadow: 0 0 0 4px rgba(239,68,68,0.3);
  animation: pulse-ring 1.8s infinite;
  cursor: pointer;
}
@keyframes pulse-ring {
  0% { transform: scale(0.9); box-shadow: 0 0 0 2px rgba(239,68,68,0.5); }
  50% { transform: scale(1.1); box-shadow: 0 0 0 7px rgba(239,68,68,0.15); }
  100% { transform: scale(0.9); box-shadow: 0 0 0 2px rgba(239,68,68,0.5); }
}

/* Right Side: AI Clinical Summary & Quick Actions */
.summary-column {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.ai-summary-card {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 14px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.ai-summary-title {
  font-size: 13px;
  font-weight: 700;
  color: #0f172a;
  display: flex;
  align-items: center;
  gap: 6px;
}
.summary-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  row-gap: 8px;
  column-gap: 8px;
  font-size: 11px;
}
.sum-label { color: #64748b; font-weight: 500; }
.sum-val { font-weight: 600; color: #2563eb; }
.sum-val.orange { color: #ea580c; }
.sum-val.score { color: #ef4444; font-size: 13px; font-weight: 800; display: flex; align-items: center; gap: 4px; }

/* Quick Actions Stack */
.actions-stack {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.btn-start-visit {
  background: #f97316;
  color: #ffffff;
  border: none;
  border-radius: var(--radius-md);
  padding: 10px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.15s ease;
  box-shadow: 0 2px 6px rgba(249,115,22,0.3);
}
.btn-start-visit:hover { background: #ea580c; }
.btn-action-outline {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 7px 12px;
  font-size: 12px;
  font-weight: 600;
  color: #334155;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: all 0.15s ease;
}
.btn-action-outline:hover { background: #f8fafc; border-color: #cbd5e1; }

/* ROW 3: 4 VITALS CHARTS + AI INSIGHT */
.vitals-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr) 1.2fr;
  gap: 12px;
}
.vital-card {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 12px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.vital-title { font-size: 11px; font-weight: 600; color: #64748b; }
.vital-val-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 4px 0 6px;
}
.vital-val { font-size: 18px; font-weight: 800; color: #0f172a; }
.vital-diff { font-size: 11px; font-weight: 700; display: flex; align-items: center; gap: 2px; }
.vital-diff.red { color: #ef4444; }
.vital-diff.green { color: #16a34a; }
.vital-chart-svg {
  width: 100%;
  height: 46px;
  overflow: visible;
}
.vital-dates {
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  color: #94a3b8;
  margin-top: 4px;
}

/* AI Insight Box */
.ai-insight-card {
  background: #fff7ed;
  border: 1px solid #fed7aa;
  border-radius: var(--radius-md);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  position: relative;
}
.insight-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #ea580c;
  font-weight: 700;
  font-size: 12px;
}
.insight-text { font-size: 11px; color: #9a3412; line-height: 1.45; }
.insight-close {
  background: transparent;
  border: none;
  color: #c2410c;
  cursor: pointer;
  font-size: 14px;
}

/* ROW 4: JOURNEY TIMELINE + DIAGNOSTIC LABS + AI COPILOT */
.bottom-row {
  display: grid;
  grid-template-columns: 1.3fr 1.7fr 1.1fr;
  gap: 12px;
}

/* Patient Journey Timeline */
.timeline-card {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 14px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.timeline-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}
.timeline-title { font-size: 13px; font-weight: 700; color: #0f172a; }
.timeline-nav-btn {
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: 50%;
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 11px;
  color: #64748b;
}

.journey-track {
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
  padding: 10px 4px;
}
.journey-line {
  position: absolute;
  left: 20px;
  right: 20px;
  top: 26px;
  height: 2px;
  background: #e2e8f0;
  z-index: 1;
}
.journey-node {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  z-index: 2;
  text-align: center;
}
.node-circle {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #ffffff;
  border: 2px solid #e2e8f0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  margin-bottom: 6px;
}
.node-title { font-size: 10px; font-weight: 700; color: #1e293b; white-space: nowrap; }
.node-date { font-size: 9px; color: #64748b; margin-top: 1px; }

/* Diagnostic Labs Table Card */
.labs-card {
  background: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 14px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
}
.labs-tabs {
  display: flex;
  gap: 16px;
  border-bottom: 1px solid #f1f5f9;
  padding-bottom: 8px;
  margin-bottom: 8px;
}
.labs-tab {
  font-size: 11.5px;
  font-weight: 600;
  color: #64748b;
  cursor: pointer;
  padding-bottom: 4px;
  position: relative;
}
.labs-tab.active {
  color: #2563eb;
  border-bottom: 2px solid #2563eb;
}
.labs-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11.5px;
}
.labs-table th {
  text-align: left;
  color: #64748b;
  font-weight: 600;
  padding: 6px 8px;
  border-bottom: 1px solid #f1f5f9;
  font-size: 10.5px;
}
.labs-table td {
  padding: 6px 8px;
  border-bottom: 1px solid #f8fafc;
  color: #1e293b;
}
.pill-status {
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10px;
