  </main>
</div>

<script>
let currentHires = false;
function toggleHires() {
  currentHires = !currentHires;
  const img = document.getElementById('bodyDisplayImg');
  if (currentHires) {
    img.src = 'data:image/jpeg;base64,';
  } else {
    img.src = 'data:image/png;base64,';
  }
}

function selectPatient(name) {
  document.querySelectorAll('.patient-card').forEach(c => c.classList.remove('active'));
  event.currentTarget.classList.add('active');
}
</script>
</body>
</html>
'@
$html | Set-Content -Path $outHtml -Encoding UTF8
